CREATE OR REPLACE FUNCTION audit.audit_trigger()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO audit.customer_audit (
            customer_id, action, changed_by, changed_at, 
            old_values, new_values
        ) VALUES (
            NEW.id, 'INSERT', 'system', NOW(), 
            NULL, row_to_json(NEW)
        );
        RETURN NEW;
    ELSIF TG_OP = 'UPDATE' THEN
        INSERT INTO audit.customer_audit (
            customer_id, action, changed_by, changed_at,
            old_values, new_values
        ) VALUES (
            NEW.id, 'UPDATE', 'system', NOW(),
            row_to_json(OLD), row_to_json(NEW)
        );
        RETURN NEW;
    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO audit.customer_audit (
            customer_id, action, changed_by, changed_at,
            old_values, new_values
        ) VALUES (
            OLD.id, 'DELETE', 'system', NOW(),
            row_to_json(OLD), NULL
        );
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS customer_audit_trigger ON customers;

CREATE TRIGGER customer_audit_trigger
    AFTER INSERT OR UPDATE OR DELETE ON customers
    FOR EACH ROW EXECUTE FUNCTION audit.audit_trigger();
